import {CONFIG} from './config.js';
import {DEVICES,STATUS,COLORS,statusOf,setScenario,getScenario} from './telemetry.js';
const $=s=>document.querySelector(s);let context,selectDevice,resetData,controller,currentSelected,uiNodes=[];let activeGroup='all',page=0,query='',statusFilter='all';
function filtered(){return DEVICES.filter(d=>(activeGroup==='all'||d.group===activeGroup)&&(!query||`${d.name} ${d.code}`.toLowerCase().includes(query))&&(statusFilter==='all'||(context&&statusOf(context.samples.get(d.id))===statusFilter)));}
function paginate(){const data=filtered(),size=CONFIG.workshop.pageSize,pages=Math.max(1,Math.ceil(data.length/size));page=Math.min(page,pages-1);const visible=new Set(data.slice(page*size,(page+1)*size).map(d=>d.id));for(const d of DEVICES)$(`.device-row[data-id="${d.id}"]`).hidden=!visible.has(d.id);$('#page-info').textContent=`${data.length?Math.min(page*size+1,data.length):0}–${Math.min((page+1)*size,data.length)} / ${data.length} 台`;$('#prev-page').disabled=page===0;$('#next-page').disabled=page>=pages-1;document.querySelectorAll('[data-group]').forEach(b=>{b.classList.toggle('active',b.dataset.group===activeGroup);b.setAttribute('aria-pressed',String(b.dataset.group===activeGroup));});}
export function selectWorkshopDevice(id){currentSelected=id;if(context){const items=filtered(),index=items.findIndex(d=>d.id===id);if(index<0){activeGroup='all';query='';statusFilter='all';$('#device-search').value='';$('#status-filter').value='all';page=Math.floor(DEVICES.findIndex(d=>d.id===id)/CONFIG.workshop.pageSize);}else page=Math.floor(index/CONFIG.workshop.pageSize);paginate();}renderMotion();}
export function setupWorkshop(state,select,reset){context=state;selectDevice=select;resetData=reset;currentSelected=state.selected;state.workshopHistory=[];state.trendScope='workshop';
 $('.hero-unit').innerHTML='kWh<br><b>今日用电</b>';
 const articles=$('.kpis').children;articles[0].querySelector('.kpi-label').textContent=CONFIG.project.site+'温度';articles[1].querySelector('.kpi-label').textContent='相对湿度';articles[1].querySelector('small').textContent='%RH';articles[2].querySelector('.kpi-label').textContent='实时总功率';articles[2].querySelector('small').textContent='kW';
 $('.scale-labels').children[1].textContent='今日累计 · 动态模拟';$('.scale-labels').children[2].textContent=CONFIG.workshop.energyReferenceKWh+' kWh 参考量程';
 const zone=document.createElement('div');zone.className='zone-environment';zone.id='zone-environment';$('.overview-block').append(zone);
 const summary=document.createElement('div');summary.className='workshop-summary';summary.innerHTML='<span>设备 <b id="equipment-total">—</b></span><span class="running">运行 <b id="running-total">—</b></span><span>待机 <b id="idle-total">—</b></span><span class="alarm">告警 <b id="workshop-alarms">—</b></span><span>离线 <b id="offline-total">—</b></span>';$('.overview-block').append(summary);
 const devices=$('.devices-panel');devices.querySelector('h3').textContent='设备运行监测';devices.querySelector('.muted').textContent=DEVICES.length+' 台 · 按模型分组';
 const filters=document.createElement('div');filters.className='equipment-filters';for(const g of [{id:'all',name:'全部'},...CONFIG.workshop.groups]){const b=document.createElement('button');b.dataset.group=g.id;b.textContent=g.name.replace('区','');b.onclick=()=>{activeGroup=g.id;page=0;paginate();};filters.append(b);}devices.insertBefore(filters,$('#device-list'));
 const picker=document.createElement('select');picker.id='status-filter';picker.setAttribute('aria-label','设备状态筛选');for(const [key,label] of [['all','全部状态'],['normal','运行'],['stopped','待机'],['warning','预警'],['fault','故障']]){const o=document.createElement('option');o.value=key;o.textContent=label;picker.append(o);}$('.search-wrap').append(picker);picker.onchange=()=>{statusFilter=picker.value;page=0;paginate();};
 $('#device-search').oninput=e=>{query=e.target.value.toLowerCase().trim();page=0;paginate();};
 const pager=document.createElement('div');pager.className='equipment-pager';pager.innerHTML='<button id="prev-page" aria-label="上一页设备">← 上一页</button><span id="page-info"></span><button id="next-page" aria-label="下一页设备">下一页 →</button>';$('#device-list').after(pager);$('#prev-page').onclick=()=>{page--;paginate();};$('#next-page').onclick=()=>{page++;paginate();};
 for(const d of DEVICES){const row=$(`.device-row[data-id="${d.id}"]`),status=document.createElement('span');status.className='device-state';row.append(status);}
 const animationPanel=$('.animation-panel');animationPanel.querySelector('h3').textContent='所选设备 · 独立动画';animationPanel.querySelector('.muted').id='motion-count';animationPanel.querySelector('.mapping-note').textContent='运动演示独立控制，不下发真实设备指令。';
 const scenario=document.createElement('select');scenario.id='demo-scenario';scenario.setAttribute('aria-label','模拟工况');scenario.innerHTML='<option value="normal">常规生产</option><option value="saving">节能运行</option><option value="alarm">异常演示</option>';scenario.value=getScenario();$('.header-right').prepend(scenario);scenario.onchange=()=>{setScenario(scenario.value);if(controller)for(const t of controller.tracks)t.initialStateApplied=false;resetData();};
 const scope=document.createElement('select');scope.id='trend-scope';scope.setAttribute('aria-label','趋势数据范围');scope.innerHTML='<option value="workshop">项目汇总</option><option value="device">所选设备</option>';$('.chart-controls').prepend(scope);scope.onchange=()=>{state.trendScope=scope.value;configureTrend();selectDevice(state.selected);};configureTrend();
 $('#export').onclick=()=>{const keys=CONFIG.metrics.map(m=>m.key),rows=[['source','scope','deviceId','name','timestamp',...keys]];for(const s of state.workshopHistory)rows.push([state.mode,'workshop','workshop',CONFIG.project.site,new Date(s.timestamp).toISOString(),...keys.map(k=>s[k]??'')]);for(const d of DEVICES)for(const s of state.history.get(d.id))rows.push([state.mode,'device',d.id,d.name,new Date(s.timestamp).toISOString(),...keys.map(k=>s[k])]);const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=CONFIG.project.filenamePrefix+'-'+state.mode+'-'+Date.now()+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);};
 $('.devices-panel .mapping-note').textContent='设备分组按模型命名推定，现场点位可配置。';$('.model-info p').textContent=CONFIG.model.metadata.meshDefinitions+' 网格 · '+CONFIG.model.metadata.animationCount+' 段动画';paginate();
}
function configureTrend(){const select=$('#trend-metric');select.replaceChildren();const keys=context.trendScope==='workshop'?['power','energy','ambientTemp','humidity']:['power','rpm','motorTemp','current','vibration','energy'];for(const key of keys){const m=CONFIG.metrics.find(m=>m.key===key),o=document.createElement('option');o.value=key;o.textContent=m.label+' · '+m.unit;select.append(o);}}
export function updateWorkshop(state){if(!context)return;const samples=DEVICES.map(d=>state.samples.get(d.id)).filter(s=>s&&statusOf(s)!=='offline');const sum=key=>samples.reduce((n,s)=>n+s[key],0),mean=key=>samples.length?sum(key)/samples.length:NaN,stamp=Math.max(0,...samples.map(s=>s.timestamp)),power=sum('power'),energy=sum('energy'),ambient=mean('ambientTemp'),humidity=mean('humidity');
 $('#rpm').textContent=samples.length?energy.toFixed(1):'—';$('#rpm-bar').style.width=Math.min(100,energy/CONFIG.workshop.energyReferenceKWh*100)+'%';$('#line-status').textContent=Number.isFinite(ambient)?ambient.toFixed(1)+'°C':'—';$('#line-status').style.color='#25282b';$('#line-foot').textContent='分区环境动态采样';$('#speed').textContent=Number.isFinite(humidity)?humidity.toFixed(1):'—';$('.kpis').children[1].querySelector('.kpi-foot').textContent=CONFIG.project.site+'平均相对湿度';$('#alarm-total').textContent=samples.length?power.toFixed(1):'—';$('#alarm-foot').textContent='全部在线设备功率汇总';
 const states=DEVICES.map(d=>statusOf(state.samples.get(d.id)));$('#equipment-total').textContent=DEVICES.length;$('#running-total').textContent=states.filter(s=>['normal','warning'].includes(s)).length;$('#idle-total').textContent=states.filter(s=>s==='stopped').length;$('#workshop-alarms').textContent=states.filter(s=>['warning','fault'].includes(s)).length;$('#offline-total').textContent=states.filter(s=>s==='offline').length;$('#demo-scenario').disabled=state.mode==='live';
 const zone=$('#zone-environment');zone.replaceChildren();for(const group of CONFIG.workshop.groups.filter(g=>g.id!=='aux')){const ss=DEVICES.filter(d=>d.group===group.id).map(d=>state.samples.get(d.id)).filter(s=>s&&statusOf(s)!=='offline'),box=document.createElement('span'),label=document.createElement('b'),data=document.createElement('small');label.textContent=group.name;data.textContent=ss.length?(ss.reduce((n,s)=>n+s.ambientTemp,0)/ss.length).toFixed(1)+'°C / '+(ss.reduce((n,s)=>n+s.humidity,0)/ss.length).toFixed(1)+'%RH':'—';box.append(label,data);zone.append(box);}
 for(const d of DEVICES){const status=statusOf(state.samples.get(d.id)),row=$(`.device-row[data-id="${d.id}"]`);row.querySelector('.device-state').textContent=STATUS[status];row.querySelector('.device-state').style.color=COLORS[status];}
 if(stamp&&state.workshopHistory.at(-1)?.timestamp!==stamp){state.workshopHistory.push({timestamp:stamp,power,energy,ambientTemp:ambient,humidity});if(state.workshopHistory.length>CONFIG.data.historyLength)state.workshopHistory.shift();}
 $('#trend-device').textContent=state.trendScope==='workshop'?CONFIG.project.site+'汇总':DEVICES.find(d=>d.id===state.selected).name;$('.trend-panel h3').firstChild.textContent=state.trendScope==='workshop'?CONFIG.project.site+'能耗 / 环境趋势 ':'设备运行趋势 ';
 if(controller){for(const t of controller.tracks){if(!t.initialStateApplied&&state.samples.has(t.device.id)){t.running=state.samples.get(t.device.id).rpm>0;t.action.paused=!t.running;t.initialStateApplied=true;}}syncMaster();}paginate();
}
export function clipLabel(name){const suffix=name.replace(/^AMI_yundong_[^_]+_/,'');return suffix.replace(/QianYinLunA.*/,'牵引 A').replace(/QianYinLunB.*/,'牵引 B').replace(/XianPanA.*/,'线盘 A').replace(/XianPanB.*/,'线盘 B').replace(/^(\d+)$/,'$1 段绞笼').replace(/^[LFS]$/,'主绞笼');}
function scopedTracks(){return context.page==='detail'?controller.tracks.filter(t=>t.device.id===context.selected):controller.tracks;}
function syncMaster(){if(!controller)return;const running=scopedTracks().some(t=>t.running),scope=context.page==='detail'?'本机':'全部';$('#animation').textContent=(running?'暂停':'播放')+scope;$('#reset-animations').textContent=scope+'复位';$('#animation').classList.toggle('active',running);$('#animation').setAttribute('aria-pressed',String(running));for(const {track,toggle} of uiNodes){toggle.textContent=track.running?'Ⅱ':'▷';toggle.classList.toggle('active',track.running);toggle.setAttribute('aria-pressed',String(track.running));}}
function renderMotion(){if(!controller)return;const tracks=controller.tracks.filter(t=>t.device.id===currentSelected),list=$('#animation-list');list.replaceChildren();uiNodes=[];$('#motion-count').textContent=tracks.length+' 段';if(!tracks.length){const p=document.createElement('p');p.className='empty-state';p.textContent='所选机组无内置动画';list.append(p);return;}
 for(const track of tracks){const row=document.createElement('div');row.className='workshop-track';const label=document.createElement('span');label.textContent=clipLabel(track.action.getClip().name);label.title=track.action.getClip().name;const toggle=document.createElement('button');toggle.setAttribute('aria-label','播放或暂停'+label.textContent);toggle.onclick=()=>{controller.toggle(track);syncMaster();};const reset=document.createElement('button');reset.textContent='↺';reset.setAttribute('aria-label','复位'+label.textContent);reset.onclick=()=>{controller.reset(track);track.action.getMixer().update(0);};const range=document.createElement('input');range.type='range';range.min=0;range.max=1000;range.step=1;range.setAttribute('aria-label',label.textContent+'动画进度');range.oninput=()=>{if(track.running)controller.toggle(track);controller.seek(track,+range.value/1000);track.action.getMixer().update(0);syncMaster();};const speed=document.createElement('select');speed.setAttribute('aria-label',label.textContent+'播放速度');for(const n of [.25,.5,1,2]){const o=document.createElement('option');o.value=n;o.textContent=n+'×';speed.append(o);}speed.value=track.speed;speed.onchange=()=>controller.speed(track,+speed.value);row.append(label,toggle,reset,range,speed);list.append(row);uiNodes.push({track,toggle,range});}syncMaster();
}
export function mountWorkshopMotion(motion,select){controller=motion;currentSelected=context.selected;$('#animation').onclick=()=>{const tracks=scopedTracks(),running=!tracks.some(t=>t.running);for(const t of tracks){t.running=running;t.action.paused=!running;}syncMaster();};$('#reset-animations').onclick=()=>{for(const t of scopedTracks())controller.reset(t);controller.tracks[0]?.action.getMixer().update(0);};updateWorkshop(context);renderMotion();return()=>{for(const {track,range} of uiNodes)if(document.activeElement!==range)range.value=track.action.time/track.action.getClip().duration*1000;};}

export function refreshMotionScope(){syncMaster();}
